import type { LexicalEditor } from "lexical";
import { HTML_EXAMPLE, MARKDOWN_EXAMPLE } from "./constants";
import {
  createEmptyEditorState,
  loadMarkdownContent,
  replaceEditorHtmlContent,
} from "./utils";

export const copyEditorOutput = async (value: string) => {
  await navigator.clipboard.writeText(value);
};

/**
 * Triggers a browser download of the given markdown as a `.md` file, reusing
 * the same serialized markdown the output panel already exposes.
 */
export const downloadMarkdownContent = (
  content: string,
  filename = "document.md"
) => {
  const blob = new Blob([content], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");

  link.href = url;
  link.download = filename.endsWith(".md") ? filename : `${filename}.md`;
  document.body.append(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
};

export const resetEditorContent = (editor: LexicalEditor) => {
  createEmptyEditorState(editor);
};

export const loadEditorHtmlExample = (editor: LexicalEditor) => {
  replaceEditorHtmlContent(editor, HTML_EXAMPLE);
};

export const loadEditorMarkdownExample = (editor: LexicalEditor) => {
  loadMarkdownContent(editor, MARKDOWN_EXAMPLE);
};

/** Shape of a single color entry in the palette. */
export interface ColorSwatch {
  /** Human-readable label (used as aria-label on the swatch button). */
  label: string;
  /** CSS color value, e.g. "#ef4444". */
  value: string;
}

/**
 * Default color palette shared by the text color and background color pickers.
 *
 * To customise the available swatches, edit this array — the order determines
 * the rendering order in the grid. Both pickers import this constant as their
 * default, but each `<ColorSwatches>` instance also accepts a custom `palette`
 * prop if you need diverging sets.
 */
export const COLOR_PALETTE: ColorSwatch[] = [
  { label: "Black", value: "#1a1a1a" },
  { label: "Dark gray", value: "#525252" },
  { label: "Gray", value: "#a3a3a3" },
  { label: "White", value: "#ffffff" },
  { label: "Red", value: "#ef4444" },
  { label: "Orange", value: "#f97316" },
  { label: "Yellow", value: "#eab308" },
  { label: "Green", value: "#22c55e" },
  { label: "Cyan", value: "#06b6d4" },
  { label: "Blue", value: "#3b82f6" },
  { label: "Violet", value: "#8b5cf6" },
  { label: "Pink", value: "#ec4899" },
  { label: "Light red", value: "#fca5a5" },
  { label: "Light yellow", value: "#fde68a" },
  { label: "Light green", value: "#bbf7d0" },
  { label: "Light blue", value: "#bfdbfe" },
];

import type { ReactNode } from "react";
import type {
  EditorChromeOptions,
  EditorFeatureFlags,
  EditorSnapshotOptions,
} from "./types";

export const DEFAULT_EDITOR_SNAPSHOT_OPTIONS = {
  emitInitialSnapshot: true,
  html: true,
  markdown: true,
  text: true,
} as const satisfies Required<EditorSnapshotOptions>;

export type ResolvedEditorSnapshotOptions = Required<EditorSnapshotOptions>;

export const resolveEditorSnapshotOptions = (
  options?: EditorSnapshotOptions
): ResolvedEditorSnapshotOptions => {
  return {
    ...DEFAULT_EDITOR_SNAPSHOT_OPTIONS,
    ...options,
  };
};

export type ResolvedEditorFeatureFlags = Required<
  Omit<EditorFeatureFlags, "snapshot">
> & {
  snapshot: ResolvedEditorSnapshotOptions;
};
export type ResolvedEditorChromeOptions = Required<EditorChromeOptions>;

export const DEFAULT_EDITOR_FEATURES = {
  exportMarkdown: true,
  floatingLinkEditor: true,
  floatingToolbar: true,
  focusOnMount: true,
  history: true,
  markdownShortcuts: true,
  slashCommand: true,
  snapshot: DEFAULT_EDITOR_SNAPSHOT_OPTIONS,
  tabIndentation: true,
} as const satisfies ResolvedEditorFeatureFlags;

export const DEFAULT_EDITOR_CHROME = {
  actionBar: true,
  footer: true,
  header: true,
  outputs: true,
  shell: true,
} as const satisfies Required<EditorChromeOptions>;

export const resolveEditorFeatures = (
  features?: EditorFeatureFlags
): ResolvedEditorFeatureFlags => {
  const { snapshot, ...flags } = features ?? {};

  return {
    ...DEFAULT_EDITOR_FEATURES,
    ...flags,
    // The nested snapshot bag is resolved separately so a partial override
    // (e.g. `{ html: false }`) never loses the sibling defaults.
    snapshot: resolveEditorSnapshotOptions(snapshot),
  };
};

export const resolveEditorChrome = (
  chrome?: EditorChromeOptions
): ResolvedEditorChromeOptions => {
  return {
    ...DEFAULT_EDITOR_CHROME,
    ...chrome,
  };
};

export const renderEditorSlot = <T>(
  slot: ReactNode | ((context: T) => ReactNode) | undefined,
  context: T
): ReactNode | undefined => {
  if (typeof slot === "function") {
    return slot(context);
  }

  return slot;
};

export const shouldRenderEditorShell = ({
  chromeShell,
  minimal,
  shellSlot,
}: {
  chromeShell: boolean;
  minimal: boolean;
  shellSlot:
    | ReactNode
    | ((context: { children: ReactNode }) => ReactNode)
    | undefined;
}) => {
  if (shellSlot !== undefined) {
    return true;
  }

  if (minimal) {
    return false;
  }

  return chromeShell;
};

import { CodeHighlightNode, CodeNode } from "@lexical/code";
import { HorizontalRuleNode } from "@lexical/extension";
import { AutoLinkNode, LinkNode } from "@lexical/link";
import { ListItemNode, ListNode } from "@lexical/list";
import type { InitialConfigType } from "@lexical/react/LexicalComposer";
import { HeadingNode, QuoteNode } from "@lexical/rich-text";
import { TableCellNode, TableNode, TableRowNode } from "@lexical/table";
import type { LexicalNodeList } from "./features";
import { editorTheme } from "./theme";

function onError(error: Error) {
  console.error("[Editor]", error);
}

/**
 * Lexical nodes that are always registered regardless of feature toggles.
 * Feature-owned nodes (image, youtube, math, collapsible, layout) are resolved
 * separately from the feature registry and appended through `featureNodes`.
 */
export const BASE_EDITOR_NODES = [
  HeadingNode,
  QuoteNode,
  ListNode,
  ListItemNode,
  CodeNode,
  CodeHighlightNode,
  LinkNode,
  AutoLinkNode,
  HorizontalRuleNode,
  TableNode,
  TableRowNode,
  TableCellNode,
];

interface CreateEditorConfigOptions {
  editable: boolean;
  /**
   * Initial-state builder run by LexicalComposer inside the very first
   * update, before any plugin mounts. Used to seed content synchronously
   * so the editor's first paint already contains the document.
   */
  editorState?: InitialConfigType["editorState"];
  /** Consumer-provided nodes appended after everything else. */
  extraNodes?: NonNullable<InitialConfigType["nodes"]>;
  /** Nodes contributed by enabled feature descriptors. */
  featureNodes?: LexicalNodeList;
  namespace?: string;
}

export const createEditorConfig = ({
  editable,
  editorState,
  namespace = "PytahEditor",
  featureNodes = [],
  extraNodes,
}: CreateEditorConfigOptions): InitialConfigType => {
  const nodes = [...BASE_EDITOR_NODES, ...featureNodes, ...(extraNodes ?? [])];

  return {
    editable,
    namespace,
    nodes,
    onError,
    theme: editorTheme,
    ...(editorState ? { editorState } : {}),
  };
};

import type { Transformer } from "@lexical/markdown";
import { createContext, useContext } from "react";

export const EditorTransformersContext = createContext<readonly Transformer[]>(
  []
);

export const useEditorTransformers = (): readonly Transformer[] => {
  return useContext(EditorTransformersContext);
};

"use client";

import type { Transformer } from "@lexical/markdown";
import type { InitialConfigType } from "@lexical/react/LexicalComposer";
import type { ComponentType } from "react";
import { FocusOnMountPlugin } from "../plugins/core/focus-on-mount";
import { MarkdownExportPlugin } from "../plugins/export-markdown/plugin";
import { FloatingToolbarPlugin } from "../plugins/floating-toolbar/plugin";
import { FloatingLinkEditorPlugin } from "../plugins/link-behavior/floating-link-editor";
import { BUILTIN_MARKDOWN_TRANSFORMERS } from "../plugins/markdown/transformers";
import { CORE_SLASH_COMMANDS } from "../plugins/slash-command/commands";
import { CORE_SLASH_COMMAND_EXECUTORS } from "../plugins/slash-command/executors";
import { SlashCommandPlugin } from "../plugins/slash-command/plugin";
import type {
  FeatureSlashCommand,
  SlashCommand,
} from "../plugins/slash-command/types";
import { replaceCurrentBlock } from "../plugins/slash-command/utils";
import type { EditorFeatureFlags, ExtraEditorFeature } from "./types";

export type ComputedNode = NonNullable<InitialConfigType["nodes"]>[number];

export type LexicalNodeList = ComputedNode[];

/**
 * One descriptor of a built-in *core* capability — behavior the base editor
 * always ships and consumers can toggle at runtime through
 * `EditorFeatureFlags`. Content features (images, tables, drawings, ...) are
 * not listed here: they ship as separate registry items and are composed via
 * `extraFeatures`, so uninstalled features never reach the bundle.
 */
export interface EditorFeature {
  /** Only mount the plugin when the editor is editable. */
  editableOnly?: boolean;
  /** Whether the feature can be toggled by name inside `EditorFeatureFlags`. */
  flag: keyof EditorFeatureFlags & string;
  /** The behavior plugin to mount on the editor. */
  plugin?: ComponentType;
}

/**
 * The ordered list of built-in core features. Nodes, transformers and slash
 * commands for removable content features live beside their features
 * (`plugins/<feature>/feature.ts`) and are wired through `extraFeatures`.
 */
export const EDITOR_FEATURES: readonly EditorFeature[] = [
  {
    editableOnly: true,
    flag: "focusOnMount",
    plugin: FocusOnMountPlugin,
  },
  {
    editableOnly: true,
    flag: "floatingLinkEditor",
    plugin: FloatingLinkEditorPlugin,
  },
  {
    editableOnly: true,
    flag: "floatingToolbar",
    plugin: FloatingToolbarPlugin,
  },
  {
    flag: "exportMarkdown",
    plugin: MarkdownExportPlugin,
  },
];

/**
 * Collects node registrations contributed by installed extras. Core nodes
 * (headings, lists, links, code, base table) are registered statically in
 * `core/config.ts` and are not affected.
 */
export const computeFeatureNodes = (
  extraFeatures?: readonly ExtraEditorFeature[]
): LexicalNodeList => {
  const nodes: LexicalNodeList = [];

  for (const extra of extraFeatures ?? []) {
    if (extra.nodes) {
      nodes.push(...extra.nodes);
    }
  }

  return nodes;
};

/**
 * Core transformer set plus every transformer contributed by installed
 * extras — this is what markdown shortcuts, seeding and snapshot reads use.
 */
export const computeEditorTransformers = (
  extraFeatures?: readonly ExtraEditorFeature[]
): readonly Transformer[] => {
  const transformers: Transformer[] = [...BUILTIN_MARKDOWN_TRANSFORMERS];

  for (const extra of extraFeatures ?? []) {
    if (extra.transformers) {
      transformers.push(...extra.transformers);
    }
  }

  return transformers;
};

const buildCoreSlashCommandEntry = (
  command: SlashCommand
): FeatureSlashCommand => ({
  command,
  run: (editor) => {
    const executor = CORE_SLASH_COMMAND_EXECUTORS[command.id];
    if (!executor) {
      return;
    }
    replaceCurrentBlock(editor, executor);
  },
});

/**
 * Core block-type commands are always available; feature-scoped entries come
 * exclusively from installed extras. The shared insert menu renders exactly
 * this resolved list.
 */
export const computeResolvedSlashCommands = (
  extraFeatures?: readonly ExtraEditorFeature[]
): readonly FeatureSlashCommand[] => {
  const commands: FeatureSlashCommand[] = CORE_SLASH_COMMANDS.map(
    buildCoreSlashCommandEntry
  );

  for (const extra of extraFeatures ?? []) {
    if (extra.slashCommands) {
      commands.push(...extra.slashCommands);
    }
  }

  return commands;
};

/**
 * Mounted by the composition surface when the `slashCommand` flag is enabled.
 * Receives the fully resolved contribution list rather than raw ids.
 */
export const renderSlashCommandPlugin = (
  commands: readonly FeatureSlashCommand[]
) => {
  return <SlashCommandPlugin commands={commands} />;
};

import type { Transformer } from "@lexical/markdown";
import type { InitialConfigType } from "@lexical/react/LexicalComposer";
import type { LexicalEditor } from "lexical";
import type { ComponentType, ReactNode } from "react";
import type { FeatureSlashCommand } from "../plugins/slash-command/types";

/**
 * A serialized view of the current editor document. Fields stay `string`
 * unconditionally: an output disabled through `features.snapshot` is never
 * computed and surfaces as `""` — it is a placeholder, not empty content.
 */
export interface EditorSnapshot {
  html: string;
  markdown: string;
  text: string;
}

/**
 * Selective snapshot serialization. Every option defaults to `true`
 * (backward compatible); a disabled output is skipped entirely instead of
 * being computed and discarded.
 */
export interface EditorSnapshotOutputs {
  /** Serialize HTML into `snapshot.html`. @default true */
  html?: boolean;
  /** Serialize markdown into `snapshot.markdown`. @default true */
  markdown?: boolean;
  /** Serialize plain text into `snapshot.text`. @default true */
  text?: boolean;
}

export interface EditorSnapshotOptions extends EditorSnapshotOutputs {
  /**
   * Emit `onChange`/`onSnapshotReady` for the initial programmatic seed
   * (`initialMarkdown`/`initialHtml`). @default true
   */
  emitInitialSnapshot?: boolean;
}

export interface EditorActionBarControls {
  onExportMarkdown?: () => void;
  onLoadHtml: () => void;
  onLoadMarkdown: () => void;
  onReset: () => void;
}

export interface EditorFooterContext {
  snapshot: EditorSnapshot;
}

export interface EditorOutputContext {
  onCopyHtml: () => void;
  onCopyMarkdown: () => void;
  snapshot: EditorSnapshot;
}

export interface EditorShellContext {
  children: ReactNode;
}

export interface EditorFeatureFlags {
  exportMarkdown?: boolean;
  floatingLinkEditor?: boolean;
  floatingToolbar?: boolean;
  focusOnMount?: boolean;
  history?: boolean;
  markdownShortcuts?: boolean;
  slashCommand?: boolean;
  /**
   * Selective snapshot serialization. Disable the outputs a consumer never
   * reads to skip their per-keystroke serialization cost entirely.
   */
  snapshot?: EditorSnapshotOptions;
  tabIndentation?: boolean;
}

/**
 * A feature contributed by a consumer at composition time. Each capability is
 * described once and its nodes, plugin, transformers and slash commands are
 * wired together by the composition surface — no internal file edits needed.
 *
 * Content features (images, tables, drawings, ...) are shipped as separate
 * registry items and composed through this interface; nothing in `core/`
 * imports them statically, so uninstalled features never reach the bundle.
 */
export interface ExtraEditorFeature {
  /** Only mount the plugin when the editor is editable. */
  editableOnly?: boolean;
  id: string;
  /** Lexical nodes contributed by the feature. */
  nodes?: NonNullable<InitialConfigType["nodes"]>;
  /** The behavior plugin to mount on the editor. */
  plugin?: ComponentType;
  /** Slash-menu entries this feature adds to the shared insert menu. */
  slashCommands?: readonly FeatureSlashCommand[];
  /** Markdown transformers contributed by the feature. */
  transformers?: Transformer[];
}

export interface EditorChromeOptions {
  actionBar?: boolean;
  footer?: boolean;
  header?: boolean;
  outputs?: boolean;
  shell?: boolean;
}

export interface EditorPluginSlots {
  afterDefault?: ReactNode;
  afterEditable?: ReactNode;
  beforeDefault?: ReactNode;
  beforeEditable?: ReactNode;
}

export interface EditorChromeSlots {
  actionBar?: ReactNode | ((controls: EditorActionBarControls) => ReactNode);
  footer?: ReactNode | ((context: EditorFooterContext) => ReactNode);
  header?: ReactNode;
  outputs?: ReactNode | ((context: EditorOutputContext) => ReactNode);
  shell?: ReactNode | ((context: EditorShellContext) => ReactNode);
  topToolbar?: ReactNode;
}

/**
 * Controls which toolbar is shown above the editor content area.
 *
 * - `false`    — no toolbar is rendered (default, fully opt-in)
 * - `"basic"`  — block-type selector, undo/redo, alignment, and indent controls
 * - `"full"`   — everything in "basic" plus inline formatting, text/bg colour
 *                pickers, and a link toggle in one single row
 */
export type EditorToolbar = false | "basic" | "full";

export interface EditorProps {
  chrome?: EditorChromeOptions;
  className?: string;
  contentClassName?: string;
  editable?: boolean;
  extraFeatures?: ExtraEditorFeature[];
  extraNodes?: NonNullable<InitialConfigType["nodes"]>;
  features?: EditorFeatureFlags;
  initialHtml?: string;
  initialMarkdown?: string;
  minimal?: boolean;
  namespace?: string;
  onChange?: (snapshot: EditorSnapshot, editor: LexicalEditor) => void;
  placeholder?: string;
  pluginSlots?: EditorPluginSlots;
  slots?: EditorChromeSlots;
  /** @default false */
  toolbar?: EditorToolbar;
}

import { $generateHtmlFromNodes, $generateNodesFromDOM } from "@lexical/html";
import type { Transformer } from "@lexical/markdown";
import {
  $convertFromMarkdownString,
  $convertToMarkdownString,
} from "@lexical/markdown";
import {
  $addUpdateTag,
  $createParagraphNode,
  $createTextNode,
  $getRoot,
  type LexicalEditor,
} from "lexical";
import { BUILTIN_MARKDOWN_TRANSFORMERS } from "../plugins/markdown/transformers";
import type { EditorSnapshot, EditorSnapshotOutputs } from "./types";

export const createEmptyEditorState = (editor: LexicalEditor) => {
  editor.update(() => {
    const root = $getRoot();
    root.clear();
    const paragraph = $createParagraphNode();
    paragraph.append($createTextNode(""));
    root.append(paragraph);
    root.selectStart();
  });
};

/** Fallback transformers used when no feature-derived set is supplied. */
const DEFAULT_MARKDOWN_TRANSFORMERS = [...BUILTIN_MARKDOWN_TRANSFORMERS];

/**
 * Reads a serialized snapshot of the current editor document. Disabled
 * outputs (via `options`) are skipped entirely — their serialization code
 * never runs — and surface as `""` on the returned snapshot.
 */
export const readEditorSnapshot = (
  editor: LexicalEditor,
  transformers: readonly Transformer[] = DEFAULT_MARKDOWN_TRANSFORMERS,
  options?: EditorSnapshotOutputs
): EditorSnapshot => {
  const serializeHtml = options?.html ?? true;
  const serializeMarkdown = options?.markdown ?? true;
  const serializeText = options?.text ?? true;

  const snapshot: EditorSnapshot = {
    html: "",
    markdown: "",
    text: "",
  };

  editor.getEditorState().read(() => {
    if (serializeHtml) {
      snapshot.html = $generateHtmlFromNodes(editor);
    }
    if (serializeMarkdown) {
      snapshot.markdown = $convertToMarkdownString([...transformers]);
    }
    if (serializeText) {
      snapshot.text = $getRoot().getTextContent();
    }
  });

  return snapshot;
};

export const readEditorTextContent = (editor: LexicalEditor): string => {
  let textContent = "";

  editor.getEditorState().read(() => {
    textContent = $getRoot().getTextContent();
  });

  return textContent;
};

export interface EditorContentLoadOptions {
  /** Place the caret at the start of the loaded content. Defaults to `true`. */
  select?: boolean;
  /**
   * Optional update tag applied via `$addUpdateTag` inside the update, so
   * update listeners can identify programmatic loads (e.g. the mount seed).
   */
  tag?: string;
}

const selectStartOfRoot = () => {
  const root = $getRoot();
  const firstDescendant = root.getFirstDescendant();
  if (firstDescendant) {
    firstDescendant.selectStart();
    return;
  }

  const firstChild = root.getFirstChild();
  if (firstChild) {
    firstChild.selectStart();
    return;
  }

  root.selectStart();
};

export const loadMarkdownContent = (
  editor: LexicalEditor,
  markdown: string,
  options?: EditorContentLoadOptions & {
    transformers?: readonly Transformer[];
  }
) => {
  const transformers = options?.transformers ?? DEFAULT_MARKDOWN_TRANSFORMERS;

  editor.update(() => {
    if (options?.tag) {
      $addUpdateTag(options.tag);
    }
    $convertFromMarkdownString(markdown, [...transformers]);
    if (options?.select !== false) {
      selectStartOfRoot();
    }
  });
};

export const replaceEditorHtmlContent = (
  editor: LexicalEditor,
  html: string,
  options?: EditorContentLoadOptions
) => {
  editor.update(() => {
    if (options?.tag) {
      $addUpdateTag(options.tag);
    }
    const parser = new DOMParser();
    const dom = parser.parseFromString(html, "text/html");
    const nodes = $generateNodesFromDOM(editor, dom);
    const root = $getRoot();

    root.clear();

    if (nodes.length === 0) {
      const paragraph = $createParagraphNode();
      paragraph.append($createTextNode(""));
      root.append(paragraph);
      if (options?.select !== false) {
        paragraph.selectStart();
      }
      return;
    }

    root.append(...nodes);
    if (options?.select !== false) {
      selectStartOfRoot();
    }
  });
};

/* Editor theme rules that must ship with the registry. The repo's app also
 * declares these in its own index.css; this file exists so installed apps
 * render correctly without replicating editor rules by hand.
 *
 * Reset <mark> UA default so the Lexical highlight theme class on the inner
 * <span> is the sole source of color. Without this, the browser's built-in
 * yellow shows through the rounded corners of the inner span (sharp 4-corner
 * artifact behind the highlight).
 */
mark {
  color: inherit;
  background-color: transparent;
}

/* Hide the scrollbar while keeping the element scrollable (editor TOC
   rail/popover, where a visible bar is noise). Pair with overflow-y-auto. */
.scrollbar-hidden {
  scrollbar-width: none;
}
.scrollbar-hidden::-webkit-scrollbar {
  display: none;
}

"use client";

import { $generateNodesFromDOM } from "@lexical/html";
import { $convertFromMarkdownString } from "@lexical/markdown";
import { LexicalComposer } from "@lexical/react/LexicalComposer";
import "./editor.css";
import { $createParagraphNode, $getRoot, type LexicalEditor } from "lexical";
import type { ReactNode } from "react";
import { useMemo, useState } from "react";
import { cn } from "@/lib/utils";
import {
  copyEditorOutput,
  loadEditorHtmlExample,
  loadEditorMarkdownExample,
  resetEditorContent,
} from "./core/actions";
import {
  type ResolvedEditorChromeOptions,
  renderEditorSlot,
  resolveEditorChrome,
  resolveEditorFeatures,
  shouldRenderEditorShell,
} from "./core/composition";
import { createEditorConfig } from "./core/config";
import { DEFAULT_PLACEHOLDER } from "./core/constants";
import {
  computeEditorTransformers,
  computeFeatureNodes,
  computeResolvedSlashCommands,
} from "./core/features";
import type {
  EditorActionBarControls,
  EditorChromeSlots,
  EditorOutputContext,
  EditorProps,
  EditorSnapshot,
} from "./core/types";
import { readEditorSnapshot } from "./core/utils";
import { EXPORT_MARKDOWN_COMMAND } from "./plugins/export-markdown/commands";
import { EditorHeader, EditorShell } from "./ui/chrome";
import { EditorContent } from "./ui/content";
import { EditorActionBar, EditorOutputGrid } from "./ui/panels";

const getEditorHeader = (
  minimal: boolean,
  chrome: ResolvedEditorChromeOptions,
  slots?: EditorChromeSlots
): ReactNode => {
  if (minimal || !chrome.header) {
    return null;
  }

  return slots?.header === undefined ? <EditorHeader /> : slots.header;
};

const getEditorActionBar = (
  minimal: boolean,
  chrome: ResolvedEditorChromeOptions,
  controls: EditorActionBarControls,
  slots?: EditorChromeSlots
): ReactNode => {
  if (minimal || !chrome.actionBar) {
    return null;
  }

  return slots?.actionBar === undefined ? (
    <EditorActionBar {...controls} />
  ) : (
    (renderEditorSlot(slots.actionBar, controls) ?? null)
  );
};

const getEditorShell = (
  minimal: boolean,
  chrome: ResolvedEditorChromeOptions,
  content: ReactNode,
  slots?: EditorChromeSlots
): ReactNode => {
  if (
    !shouldRenderEditorShell({
      chromeShell: chrome.shell,
      minimal,
      shellSlot: slots?.shell,
    })
  ) {
    return content;
  }

  return slots?.shell === undefined ? (
    <EditorShell>{content}</EditorShell>
  ) : (
    (renderEditorSlot(slots.shell, { children: content }) ?? null)
  );
};

const getEditorOutputs = (
  minimal: boolean,
  chrome: ResolvedEditorChromeOptions,
  context: EditorOutputContext,
  slots?: EditorChromeSlots
): ReactNode => {
  if (minimal || !chrome.outputs) {
    return null;
  }

  return slots?.outputs === undefined ? (
    <EditorOutputGrid
      onCopyHtml={context.onCopyHtml}
      onCopyMarkdown={context.onCopyMarkdown}
      snapshot={context.snapshot}
    />
  ) : (
    (renderEditorSlot(slots.outputs, context) ?? null)
  );
};

export function Editor({
  className,
  chrome,
  contentClassName,
  editable = true,
  extraFeatures,
  extraNodes,
  features,
  initialHtml,
  initialMarkdown,
  minimal = false,
  namespace,
  onChange,
  placeholder = DEFAULT_PLACEHOLDER,
  pluginSlots,
  slots,
  toolbar = false,
}: EditorProps) {
  const [textContent, setTextContent] = useState("");
  const [serializedSnapshot, setSerializedSnapshot] = useState<EditorSnapshot>({
    html: "",
    markdown: "",
    text: "",
  });
  const [editorInstance, setEditorInstance] = useState<LexicalEditor | null>(
    null
  );

  const resolvedChrome = useMemo(() => resolveEditorChrome(chrome), [chrome]);
  const resolvedFeatures = useMemo(
    () => resolveEditorFeatures(features),
    [features]
  );

  // Seed props are initial-only by contract (consumers remount via `key`),
  // so they are captured once per mount.
  const [seedInput] = useState(() => ({
    html: initialHtml,
    markdown: initialMarkdown,
  }));
  const seededViaConfig = Boolean(seedInput.markdown || seedInput.html);

  // Derived registries are memoized so their identities stay stable across
  // re-renders (the editor state flows into React state on every keystroke);
  // otherwise every consumer of these props reconciles on each update.
  const featureNodes = useMemo(
    () => computeFeatureNodes(extraFeatures),
    [extraFeatures]
  );
  const transformers = useMemo(
    () => computeEditorTransformers(extraFeatures),
    [extraFeatures]
  );
  const commands = useMemo(
    () => computeResolvedSlashCommands(extraFeatures),
    [extraFeatures]
  );

  // Content is seeded inside LexicalComposer's *first* editor state (Lexical
  // runs this function in the initial update, before any plugin mounts), so
  // the very first paint of the editor already contains the document. A
  // post-mount effect paints an empty editor first and then re-populates the
  // whole document — a visible "content appears late" delay.
  const seedEditorState = seededViaConfig
    ? (editor: LexicalEditor) => {
        const root = $getRoot();
        root.clear();
        if (seedInput.markdown) {
          $convertFromMarkdownString(seedInput.markdown, [...transformers]);
          return;
        }
        const dom = new DOMParser().parseFromString(
          seedInput.html ?? "",
          "text/html"
        );
        root.append(...$generateNodesFromDOM(editor, dom));
        if (root.getChildrenSize() === 0) {
          root.append($createParagraphNode());
        }
      }
    : undefined;

  const initialConfig = createEditorConfig({
    editable,
    namespace,
    featureNodes,
    extraNodes,
    editorState: seedEditorState,
  });

  const snapshot: EditorSnapshot = {
    ...serializedSnapshot,
    text: textContent,
  };

  const handleSnapshotChange = (nextText: string, editor: LexicalEditor) => {
    setTextContent(nextText);
    setEditorInstance((currentEditor) => currentEditor ?? editor);
    (window as unknown as { __editor?: LexicalEditor }).__editor = editor;
  };

  const handleSnapshotReady = (
    nextSnapshot: EditorSnapshot,
    editor: LexicalEditor
  ) => {
    setSerializedSnapshot((currentSnapshot) => {
      if (
        currentSnapshot.html === nextSnapshot.html &&
        currentSnapshot.markdown === nextSnapshot.markdown &&
        currentSnapshot.text === nextSnapshot.text
      ) {
        return currentSnapshot;
      }

      return nextSnapshot;
    });
    setEditorInstance((currentEditor) => currentEditor ?? editor);
    onChange?.(nextSnapshot, editor);
  };

  // Snapshot serialization options are resolved with the feature flags; the
  // editor-level handlers (copy, reset, example loaders) must respect the
  // same gating so disabled outputs are never assumed to be real content.
  const snapshotOptions = resolvedFeatures.snapshot;

  const readSerializedOutput = (output: "html" | "markdown"): string => {
    if (!editorInstance) {
      return "";
    }

    return readEditorSnapshot(
      editorInstance,
      transformers,
      output === "html"
        ? { html: true, markdown: false, text: false }
        : { html: false, markdown: true, text: false }
    )[output];
  };

  const handleCopyMarkdown = async () => {
    // When an output is disabled its stored snapshot is a "" placeholder —
    // serialize on demand so the outputs panel still copies real content.
    await copyEditorOutput(
      snapshotOptions.markdown
        ? serializedSnapshot.markdown
        : readSerializedOutput("markdown")
    );
  };

  const handleCopyHtml = async () => {
    await copyEditorOutput(
      snapshotOptions.html
        ? serializedSnapshot.html
        : readSerializedOutput("html")
    );
  };

  const handleExportMarkdown = () => {
    if (!editorInstance) {
      return;
    }

    editorInstance.dispatchCommand(EXPORT_MARKDOWN_COMMAND, undefined);
  };

  const handleReset = () => {
    if (!editorInstance) {
      return;
    }

    resetEditorContent(editorInstance);
    const nextSnapshot = readEditorSnapshot(
      editorInstance,
      transformers,
      snapshotOptions
    );
    setTextContent(nextSnapshot.text);
    setSerializedSnapshot(nextSnapshot);
    onChange?.(nextSnapshot, editorInstance);
  };

  const handleLoadHtmlExample = () => {
    if (!editorInstance) {
      return;
    }

    loadEditorHtmlExample(editorInstance);
    const nextSnapshot = readEditorSnapshot(
      editorInstance,
      transformers,
      snapshotOptions
    );
    setTextContent(nextSnapshot.text);
    setSerializedSnapshot(nextSnapshot);
    onChange?.(nextSnapshot, editorInstance);
  };

  const handleLoadMarkdownExample = () => {
    if (!editorInstance) {
      return;
    }

    loadEditorMarkdownExample(editorInstance);
    const nextSnapshot = readEditorSnapshot(
      editorInstance,
      transformers,
      snapshotOptions
    );
    setTextContent(nextSnapshot.text);
    setSerializedSnapshot(nextSnapshot);
    onChange?.(nextSnapshot, editorInstance);
  };

  const actionBarControls: EditorActionBarControls = {
    onExportMarkdown: resolvedFeatures.exportMarkdown
      ? handleExportMarkdown
      : undefined,
    onLoadHtml: handleLoadHtmlExample,
    onLoadMarkdown: handleLoadMarkdownExample,
    onReset: handleReset,
  };

  const defaultContent = (
    <EditorContent
      commands={commands}
      contentClassName={contentClassName}
      editable={editable}
      extraFeatures={extraFeatures ?? []}
      features={resolvedFeatures}
      footerSlot={slots?.footer}
      initialHtml={initialHtml}
      initialMarkdown={initialMarkdown}
      minimal={minimal}
      onSnapshotChange={handleSnapshotChange}
      onSnapshotReady={handleSnapshotReady}
      placeholder={placeholder}
      pluginSlots={pluginSlots}
      seededViaConfig={seededViaConfig}
      showFooter={!minimal && resolvedChrome.footer}
      snapshot={snapshot}
      toolbar={toolbar}
      topToolbar={slots?.topToolbar}
      transformers={transformers}
    />
  );

  const headerContent = getEditorHeader(minimal, resolvedChrome, slots);
  const actionBarContent = getEditorActionBar(
    minimal,
    resolvedChrome,
    actionBarControls,
    slots
  );

  const shellChildren = (
    <>
      {headerContent}
      {actionBarContent}
      {defaultContent}
    </>
  );

  const editorBody = getEditorShell(
    minimal,
    resolvedChrome,
    minimal ? defaultContent : shellChildren,
    slots
  );

  const outputContent = getEditorOutputs(
    minimal,
    resolvedChrome,
    {
      onCopyHtml: handleCopyHtml,
      onCopyMarkdown: handleCopyMarkdown,
      snapshot,
    },
    slots
  );

  return (
    <div className={cn(!minimal && "space-y-6", className)}>
      <LexicalComposer initialConfig={initialConfig}>
        {editorBody}
      </LexicalComposer>

      {outputContent}
    </div>
  );
}

"use client";

import type { LexicalEditor } from "lexical";
import { CheckIcon, ChevronDownIcon } from "lucide-react";
import { memo } from "react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { getSlashRunner } from "../slash-command/executors";
import {
  BLOCK_ICONS,
  BLOCK_LABELS,
  BLOCK_OPTIONS,
  getAvailableBlockOptions,
  INSERT_SECTION_TYPES,
} from "./options";
import type { BlockOption, BlockTypeValue } from "./types";
import { applyBlockType, getCurrentBlockOption } from "./utils";

const isConversionOption = (option: BlockOption): boolean =>
  !INSERT_SECTION_TYPES.has(option.value);

interface BlockTypeDropProps {
  blockType: BlockTypeValue;
  className?: string;
  /**
   * Slash command ids resolved from the enabled feature set. Options whose
   * commands are feature-gated only render when their id is present. When
   * omitted, every block option renders.
   */
  commandIds?: readonly string[];
  editor: LexicalEditor;
  onBlockTypeChange?: (value: BlockTypeValue) => void;
}

export const BlockTypeDrop = memo(function BlockTypeDrop({
  blockType,
  className,
  commandIds,
  editor,
  onBlockTypeChange,
}: BlockTypeDropProps) {
  const availableOptions = getAvailableBlockOptions(
    commandIds ?? BLOCK_OPTIONS.map((option) => option.value)
  );
  const conversionOptions = availableOptions.filter(isConversionOption);
  const insertOptions = availableOptions.filter(
    (option) => !isConversionOption(option)
  );

  const currentOption = getCurrentBlockOption(blockType, availableOptions);
  const CurrentIcon = BLOCK_ICONS[currentOption?.value ?? "paragraph"];

  const handleChange = (value: BlockTypeValue) => {
    if (INSERT_SECTION_TYPES.has(value)) {
      getSlashRunner(value)?.(editor);
      return;
    }

    applyBlockType(editor, value);
    onBlockTypeChange?.(value);
  };

  const renderOption = (option: BlockOption) => {
    const Icon = BLOCK_ICONS[option.value];
    const isSelected = option.value === blockType;

    return (
      <DropdownMenuItem
        className={cn(
          "items-start gap-3 px-3 py-2",
          isSelected && "bg-accent/40"
        )}
        key={option.value}
        onClick={() => handleChange(option.value)}
      >
        <span className="mt-0.5 rounded-sm bg-muted p-1 text-muted-foreground">
          <Icon className="size-4" />
        </span>
        <span className="flex flex-col">
          <span className="font-medium text-foreground text-sm">
            {option.label}
          </span>
          <span className="text-muted-foreground text-xs">
            {option.description}
          </span>
        </span>
        {isSelected && (
          <CheckIcon className="ml-auto size-3.5 shrink-0 self-center text-muted-foreground" />
        )}
      </DropdownMenuItem>
    );
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button size="sm" variant="outline" />}>
        <CurrentIcon className="size-4" />
        <span>{currentOption?.label ?? BLOCK_LABELS.paragraph}</span>
        <ChevronDownIcon className="size-4 text-muted-foreground" />
      </DropdownMenuTrigger>

      <DropdownMenuContent className={cn("w-72", className)}>
        <DropdownMenuGroup>
          <DropdownMenuLabel>Turn into</DropdownMenuLabel>
          {conversionOptions.map(renderOption)}
        </DropdownMenuGroup>

        {insertOptions.length > 0 && (
          <DropdownMenuGroup>
            <DropdownMenuSeparator />
            <DropdownMenuLabel>Insert</DropdownMenuLabel>
            {insertOptions.map(renderOption)}
          </DropdownMenuGroup>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
});

