interface BlockTypeToolbarPluginProps {
  /** Slash command ids resolved from the enabled feature set. */
  commandIds?: readonly string[];
}

export const BlockTypeToolbarPlugin = memo(function BlockTypeToolbarPlugin({
  commandIds,
}: BlockTypeToolbarPluginProps) {
  const [editor] = useLexicalComposerContext();
  const [currentBlockType, setCurrentBlockType] =
    useState<BlockTypeValue>("paragraph");

  useEffect(() => {
    function updateCurrentBlockType() {
      editor.getEditorState().read(() => {
        const blockType = getBlockTypeFromSelection();
        const resolvedBlockType = blockType ?? "paragraph";

        setCurrentBlockType((current) =>
          current === resolvedBlockType ? current : resolvedBlockType
        );
      });
    }

    return mergeRegister(
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          updateCurrentBlockType();
          return false;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerUpdateListener(updateCurrentBlockType)
    );
  }, [editor]);

  return (
    <div className="flex items-center gap-1">
      <TooltipProvider>
        <BlockTypeDrop
          blockType={currentBlockType}
          commandIds={commandIds}
          editor={editor}
          onBlockTypeChange={setCurrentBlockType}
        />

        <Separator className="mx-1 h-5" orientation="vertical" />

        <ToolbarTooltip label="Undo">
          <Button
            aria-label="Undo"
            onClick={() => editor.dispatchCommand(UNDO_COMMAND, undefined)}
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <UndoIcon />
          </Button>
        </ToolbarTooltip>
        <ToolbarTooltip label="Redo">
          <Button
            aria-label="Redo"
            onClick={() => editor.dispatchCommand(REDO_COMMAND, undefined)}
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <RedoIcon />
          </Button>
        </ToolbarTooltip>

        <Separator className="mx-1 h-5" orientation="vertical" />

        <ToolbarTooltip label="Align left">
          <Button
            aria-label="Align left"
            onClick={() =>
              editor.dispatchCommand(FORMAT_ELEMENT_COMMAND, "left")
            }
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <AlignLeftIcon />
          </Button>
        </ToolbarTooltip>
        <ToolbarTooltip label="Align center">
          <Button
            aria-label="Align center"
            onClick={() =>
              editor.dispatchCommand(FORMAT_ELEMENT_COMMAND, "center")
            }
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <AlignCenterIcon />
          </Button>
        </ToolbarTooltip>
        <ToolbarTooltip label="Align right">
          <Button
            aria-label="Align right"
            onClick={() =>
              editor.dispatchCommand(FORMAT_ELEMENT_COMMAND, "right")
            }
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <AlignRightIcon />
          </Button>
        </ToolbarTooltip>

        <Separator className="mx-1 h-5" orientation="vertical" />

        <ToolbarTooltip label="Outdent">
          <Button
            aria-label="Outdent"
            onClick={() =>
              editor.dispatchCommand(OUTDENT_CONTENT_COMMAND, undefined)
            }
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <IndentDecreaseIcon />
          </Button>
        </ToolbarTooltip>
        <ToolbarTooltip label="Indent">
          <Button
            aria-label="Indent"
            onClick={() =>
              editor.dispatchCommand(INDENT_CONTENT_COMMAND, undefined)
            }
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <IndentIncreaseIcon />
          </Button>
        </ToolbarTooltip>
      </TooltipProvider>
    </div>
  );
});

import type { SlashCommandId } from "../slash-command/types";

/**
 * Block types available in toolbar dropdowns mirror the slash command ids so
 * both surfaces stay in sync by construction.
 */
export type BlockTypeValue = SlashCommandId;

export interface BlockOption {
  alwaysOn?: boolean;
  description: string;
  label: string;
  value: BlockTypeValue;
}

import { $createCodeNode, $isCodeNode } from "@lexical/code";
import {
  $isListNode,
  INSERT_CHECK_LIST_COMMAND,
  INSERT_ORDERED_LIST_COMMAND,
  INSERT_UNORDERED_LIST_COMMAND,
  REMOVE_LIST_COMMAND,
} from "@lexical/list";
import {
  $createHeadingNode,
  $createQuoteNode,
  $isHeadingNode,
  $isQuoteNode,
} from "@lexical/rich-text";
import { $setBlocksType } from "@lexical/selection";
import { $isTableNode, INSERT_TABLE_COMMAND } from "@lexical/table";
import {
  $createParagraphNode,
  $findMatchingParent,
  $getSelection,
  $isParagraphNode,
  $isRangeSelection,
  type LexicalEditor,
  type LexicalNode,
  type RangeSelection,
} from "lexical";
import { getSlashRunner } from "../slash-command/executors";
import type { BlockOption, BlockTypeValue } from "./types";

const HEADING_VALUES = ["h1", "h2", "h3"] as const;

const EXECUTOR_BLOCK_TYPES = [
  "collapsible",
  "columns",
  "excalidraw",
  "hr",
  "math",
] as const satisfies readonly BlockTypeValue[];

const isExecutorBlockType = (
  value: BlockTypeValue
): value is (typeof EXECUTOR_BLOCK_TYPES)[number] => {
  return EXECUTOR_BLOCK_TYPES.includes(
    value as (typeof EXECUTOR_BLOCK_TYPES)[number]
  );
};

const isHeadingValue = (
  value: BlockTypeValue
): value is (typeof HEADING_VALUES)[number] => {
  return HEADING_VALUES.includes(value as (typeof HEADING_VALUES)[number]);
};

const findSelectedTableAncestor = (node: LexicalNode) => {
  return $findMatchingParent(node, (parentNode) => $isTableNode(parentNode));
};

export const getBlockTypeFromSelection = (): BlockTypeValue | null => {
  const selection = $getSelection();
  if (!$isRangeSelection(selection)) {
    return null;
  }

  const anchorNode = selection.anchor.getNode();

  if (findSelectedTableAncestor(anchorNode)) {
    return "table";
  }

  const topLevelElement = anchorNode.getTopLevelElementOrThrow();

  if ($isHeadingNode(topLevelElement)) {
    const headingTag = topLevelElement.getTag();
    if (headingTag === "h1" || headingTag === "h2" || headingTag === "h3") {
      return headingTag;
    }

    return null;
  }

  if ($isQuoteNode(topLevelElement)) {
    return "quote";
  }

  if ($isCodeNode(topLevelElement)) {
    return "code";
  }

  if ($isListNode(topLevelElement)) {
    const listType = topLevelElement.getListType();
    if (
      listType === "bullet" ||
      listType === "number" ||
      listType === "check"
    ) {
      return listType;
    }

    return null;
  }

  if ($isParagraphNode(topLevelElement)) {
    return "paragraph";
  }

  return null;
};

const $applyConversionBlockType = (
  selection: RangeSelection,
  blockType: BlockTypeValue
): boolean => {
  if (blockType === "paragraph") {
    $setBlocksType(selection, () => $createParagraphNode());
    return true;
  }

  if (isHeadingValue(blockType)) {
    $setBlocksType(selection, () => $createHeadingNode(blockType));
    return true;
  }

  if (blockType === "quote") {
    $setBlocksType(selection, () => $createQuoteNode());
    return true;
  }

  if (blockType === "code") {
    $setBlocksType(selection, () => $createCodeNode());
    return true;
  }

  return false;
};

export const applyBlockType = (
  editor: LexicalEditor,
  blockType: BlockTypeValue
) => {
  // Insert-style blocks reuse the slash command runners so every surface
  // (slash menu, toolbar, dialogs) produces identical results. Feature runs
  // come from the runtime registry — no static feature imports here.
  if (isExecutorBlockType(blockType)) {
    const run = getSlashRunner(blockType);
    if (run) {
      run(editor);
      return;
    }
  }

  editor.update(() => {
    const selection = $getSelection();
    if (!$isRangeSelection(selection)) {
      return;
    }

    if ($applyConversionBlockType(selection, blockType)) {
      return;
    }

    if (blockType === "table") {
      editor.dispatchCommand(INSERT_TABLE_COMMAND, {
        columns: "3",
        includeHeaders: true,
        rows: "3",
      });
      return;
    }

    editor.dispatchCommand(REMOVE_LIST_COMMAND, undefined);

    if (blockType === "bullet") {
      editor.dispatchCommand(INSERT_UNORDERED_LIST_COMMAND, undefined);
      return;
    }

    if (blockType === "check") {
      editor.dispatchCommand(INSERT_CHECK_LIST_COMMAND, undefined);
      return;
    }

    editor.dispatchCommand(INSERT_ORDERED_LIST_COMMAND, undefined);
  });
};

export const getCurrentBlockOption = (
  currentBlockType: BlockTypeValue,
  options: BlockOption[]
): BlockOption => {
  return (
    options.find((option) => option.value === currentBlockType) ?? options[0]
  );
};

"use client";

import { $isCodeNode, CodeNode } from "@lexical/code";
import {
  loadCodeTheme,
  registerCodeHighlighting,
  ShikiTokenizer,
} from "@lexical/code-shiki";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  $getRoot,
  $getSelection,
  $isElementNode,
  $isRangeSelection,
  type LexicalNode,
  SKIP_DOM_SELECTION_TAG,
} from "lexical";
import { useEffect, useState } from "react";
import { useTheme } from "@/components/theme-context";

const CODE_BLOCK_THEME_BY_MODE = {
  dark: "github-dark",
  light: "github-light",
} as const;

let shikiThemesPreloaded = false;

const preloadShikiThemes = () => {
  if (shikiThemesPreloaded) {
    return;
  }
  shikiThemesPreloaded = true;
  for (const theme of Object.values(CODE_BLOCK_THEME_BY_MODE)) {
    loadCodeTheme(theme)?.catch(() => undefined);
  }
};

const $selectionIsInside = (node: LexicalNode): boolean => {
  const selection = $getSelection();
  if (!$isRangeSelection(selection)) {
    return false;
  }
  const anchorNode = selection.anchor.getNode();
  return anchorNode === node || node.isParentOf(anchorNode);
};

const $rethemeCodeNode = (node: CodeNode, codeBlockTheme: string): void => {
  // When the caret lives inside this code node, shiki's own
  // selection-retention logic is correct and handles the swap.
  if ($selectionIsInside(node)) {
    node.setTheme(codeBlockTheme);
    return;
  }

  // Otherwise re-tokenize inline so shiki's own transform diffs to a no-op.
  // Without this, its $updateAndRetainSelection pulls the out-of-node caret
  // into the code block and the browser scrolls it into view (theme-toggle
  // scroll jump).
  try {
    const tokens = ShikiTokenizer.$tokenize(
      node,
      node.getLanguage() ?? ShikiTokenizer.defaultLanguage
    );
    node.splice(0, node.getChildrenSize(), tokens);
  } catch {
    // Shiki theme/language not loaded yet — let the node transform finish
    // the swap through its async loading flow.
  }
  node.setTheme(codeBlockTheme);
};

const $rethemeStaleCodeNodes = (codeBlockTheme: string): void => {
  const queue: LexicalNode[] = [$getRoot()];
  while (queue.length > 0) {
    const node = queue.shift();
    if (!node) {
      continue;
    }

    if ($isCodeNode(node)) {
      if (node.getTheme() !== codeBlockTheme) {
        $rethemeCodeNode(node, codeBlockTheme);
      }
    } else if ($isElementNode(node)) {
      queue.push(...node.getChildren());
    }
  }
};

export function CodeHighlightPlugin() {
  const [editor] = useLexicalComposerContext();
  const { resolvedTheme } = useTheme();
  const codeBlockTheme = CODE_BLOCK_THEME_BY_MODE[resolvedTheme];

  // Shiki tokenization + per-node diff/re-splice is the most expensive
  // synchronous work an editor mount can do; with many code blocks the
  // chained async→sync updates starve the first paint (observed multi-second
  // blank freeze opening a code-heavy document). Arm highlighting after the
  // document has painted: content shows first as plain code text, colors
  // land one frame later, off the critical path.
  const [armed, setArmed] = useState(false);

  useEffect(() => {
    if (armed) {
      return;
    }
    let raf2 = 0;
    const raf1 = requestAnimationFrame(() => {
      raf2 = requestAnimationFrame(() => {
        setArmed(true);
      });
    });
    return () => {
      cancelAnimationFrame(raf1);
      if (raf2) {
        cancelAnimationFrame(raf2);
      }
    };
  }, [armed]);

  useEffect(() => {
    if (!armed) {
      return;
    }
    return registerCodeHighlighting(editor);
  }, [armed, editor]);

  useEffect(() => {
    if (!armed) {
      return;
    }
    return editor.registerNodeTransform(CodeNode, (codeNode) => {
      if (codeNode.getTheme() !== codeBlockTheme) {
        codeNode.setTheme(codeBlockTheme);
      }
    });
  }, [armed, codeBlockTheme, editor]);

  useEffect(() => {
    if (!armed) {
      return;
    }
    preloadShikiThemes();

    editor.update(
      () => {
        $rethemeStaleCodeNodes(codeBlockTheme);
      },
      // Cosmetic-only update: without this tag Lexical re-applies the DOM
      // selection, which implicitly refocuses the contenteditable and makes
      // the browser scroll to the caret (e.g. when toggling themes).
      { discrete: true, tag: SKIP_DOM_SELECTION_TAG }
    );
  }, [armed, codeBlockTheme, editor]);

  return null;
}

