import type { Transformer } from "@lexical/markdown";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import type { EditorState, LexicalEditor } from "lexical";
import { HISTORY_MERGE_TAG } from "lexical";
import { useEffect, useEffectEvent, useRef, useState } from "react";
import {
  DEFAULT_EDITOR_SNAPSHOT_OPTIONS,
  type ResolvedEditorSnapshotOptions,
} from "../../core/composition";
import { EDITOR_SEED_UPDATE_TAG } from "../../core/constants";
import type { EditorSnapshot } from "../../core/types";
import {
  loadMarkdownContent,
  readEditorSnapshot,
  readEditorTextContent,
  replaceEditorHtmlContent,
} from "../../core/utils";

export interface EditorStatePluginProps {
  initialHtml?: string;
  initialMarkdown?: string;
  onChange?: (textContent: string, editor: LexicalEditor) => void;
  onSnapshotReady?: (snapshot: EditorSnapshot, editor: LexicalEditor) => void;
  /**
   * When true the seed was already applied synchronously through the
   * composer's `initialConfig.editorState` — no post-mount seeding is done,
   * only the optional initial snapshot emission is replayed here.
   */
  seededViaConfig?: boolean;
  /**
   * Resolved snapshot serialization options (see `features.snapshot` on
   * `Editor`). Disabled outputs are skipped entirely; defaults to all-on.
   */
  snapshotOptions?: ResolvedEditorSnapshotOptions;
  transformers?: readonly Transformer[];
}

/** Structural subset of Lexical's update-listener payload used for filtering. */
export interface SnapshotUpdateSignal {
  dirtyElements: { readonly size: number };
  dirtyLeaves: { readonly size: number };
  prevEditorState: EditorState;
  tags: ReadonlySet<string>;
}

/**
 * Decides whether an editor update should produce serialized outputs.
 * Mirrors OnChangePlugin semantics (selection-only, history-merge and
 * initial-empty updates are ignored) plus suppression of the tagged mount
 * seed when `emitInitialSnapshot` is `false`.
 */
export const shouldEmitSnapshotUpdate = (
  update: SnapshotUpdateSignal,
  options: { emitInitialSnapshot: boolean }
): boolean => {
  if (update.dirtyElements.size === 0 && update.dirtyLeaves.size === 0) {
    return false;
  }
  if (update.tags.has(HISTORY_MERGE_TAG)) {
    return false;
  }
  if (update.prevEditorState.isEmpty()) {
    return false;
  }
  if (!options.emitInitialSnapshot && update.tags.has(EDITOR_SEED_UPDATE_TAG)) {
    return false;
  }
  return true;
};

export function EditorStatePlugin({
  initialHtml,
  initialMarkdown,
  onChange,
  onSnapshotReady,
  seededViaConfig = false,
  snapshotOptions = DEFAULT_EDITOR_SNAPSHOT_OPTIONS,
  transformers,
}: EditorStatePluginProps) {
  const [editor] = useLexicalComposerContext();

  // `initial*` props are initial-only by contract: the seed is captured once
  // per mount and never re-applied when prop identities change. Consumers
  // remount via `key` instead — re-seeding in place would replace live state
  // and reset the caret.
  const [seed] = useState(() => ({
    html: initialHtml,
    markdown: initialMarkdown,
  }));

  const seedEditor = useEffectEvent(() => {
    if (seed.markdown) {
      loadMarkdownContent(editor, seed.markdown, {
        select: false,
        tag: EDITOR_SEED_UPDATE_TAG,
        transformers,
      });
      return;
    }

    if (seed.html) {
      replaceEditorHtmlContent(editor, seed.html, {
        select: false,
        tag: EDITOR_SEED_UPDATE_TAG,
      });
    }
  });

  const emitInitialSnapshot = useEffectEvent(() => {
    if (snapshotOptions.text) {
      onChange?.(readEditorTextContent(editor), editor);
    }

    if (snapshotOptions.html || snapshotOptions.markdown) {
      onSnapshotReady?.(
        readEditorSnapshot(editor, transformers, snapshotOptions),
        editor
      );
    }
  });

  // When the seed was applied through the composer's initial state there is
  // no seed update to observe, so the initial snapshot (when enabled) is
  // emitted directly from the already-populated state. The emission is
  // deferred one microtask because the composer's initial update commits
  // asynchronously (scheduleMicroTask) — this keeps the read deterministic
  // whether effects flush before or after that commit. The post-mount
  // seeding path remains for standalone plugin usage.
  const didEmitInitialRef = useRef(false);

  const emitConfiguredSeedSnapshot = useEffectEvent(() => {
    if (!snapshotOptions.emitInitialSnapshot) {
      return;
    }
    if (!(seed.markdown || seed.html)) {
      return;
    }
    if (didEmitInitialRef.current) {
      return;
    }
    didEmitInitialRef.current = true;
    queueMicrotask(() => {
      emitInitialSnapshot();
    });
  });

  const runMountSeed = useEffectEvent(() => {
    if (seededViaConfig) {
      emitConfiguredSeedSnapshot();
      return;
    }
    seedEditor();
  });

  useEffect(() => {
    runMountSeed();
  }, []);

  const handleUpdate = useEffectEvent((update: SnapshotUpdateSignal) => {
    if (!shouldEmitSnapshotUpdate(update, snapshotOptions)) {
      return;
    }

    if (snapshotOptions.text) {
      onChange?.(readEditorTextContent(editor), editor);
    }

    if (snapshotOptions.html || snapshotOptions.markdown) {
      onSnapshotReady?.(
        readEditorSnapshot(editor, transformers, snapshotOptions),
        editor
      );
    }
  });

  useEffect(() => {
    return editor.registerUpdateListener(handleUpdate);
  }, [editor]);

  return null;
}

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $getRoot } from "lexical";
import { useEffect, useRef } from "react";

const SETTLE_RETRY_DELAY_MS = 150;

export function FocusOnMountPlugin() {
  const [editor] = useLexicalComposerContext();
  const retryTimersRef = useRef<number[]>([]);
  const didPlaceCaretRef = useRef(false);

  useEffect(() => {
    let cancelled = false;

    const clearRetryTimers = () => {
      for (const timer of retryTimersRef.current) {
        window.clearTimeout(timer);
      }
      retryTimersRef.current = [];
    };

    const placeMountCaret = () => {
      // Idempotent: once the mount caret is placed, never move it again.
      // Late triggers (window load, fonts.ready, fallback timer, retries)
      // would otherwise yank the caret back to the start of the first block
      // even after the user has already moved it.
      if (didPlaceCaretRef.current) {
        return true;
      }

      const rootElement = editor.getRootElement();
      if (rootElement?.contains(document.activeElement)) {
        didPlaceCaretRef.current = true;
        return true;
      }

      const hasContent = editor
        .getEditorState()
        .read(() => $getRoot().getFirstDescendant() !== null);
      if (!hasContent) {
        return false;
      }

      editor.update(() => {
        const root = $getRoot();
        const firstDescendant = root.getFirstDescendant();
        if (firstDescendant) {
          firstDescendant.selectStart();
        } else {
          const firstChild = root.getFirstChild();
          if (firstChild) {
            firstChild.selectStart();
          } else {
            root.selectStart();
          }
        }
      });

      if (rootElement) {
        rootElement.focus({ preventScroll: true });
      }
      didPlaceCaretRef.current = true;

      return true;
    };

    const settle = () => {
      if (cancelled) {
        return;
      }

      // Wait one frame so any in-flight layout pass is applied before the
      // caret is placed. Placing the caret before async assets (KaTeX fonts,
      // images) finish loading makes the browser scroll the caret back into
      // view when those assets later shift the layout, yanking the page away
      // from its position.
      requestAnimationFrame(() => {
        if (cancelled) {
          return;
        }

        if (!placeMountCaret()) {
          const retryTimer = window.setTimeout(settle, SETTLE_RETRY_DELAY_MS);
          retryTimersRef.current.push(retryTimer);
        }
      });
    };

    const release = () => {
      if (cancelled) {
        return;
      }
      cancelled = true;
      window.removeEventListener("load", settle);
      clearRetryTimers();
    };

    window.addEventListener("load", settle);
    const fontsReady = document.fonts
      ? document.fonts.ready
      : Promise.resolve();
    fontsReady.then(settle).catch(settle);
    const fallbackTimer = window.setTimeout(settle, 1000);

    return () => {
      if (!cancelled) {
        release();
      }
      window.clearTimeout(fallbackTimer);
    };
  }, [editor]);

  return null;
}

"use client";

import {
  $createHorizontalRuleNode,
  $isHorizontalRuleNode,
  HorizontalRuleNode,
  INSERT_HORIZONTAL_RULE_COMMAND,
} from "@lexical/extension";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  $insertNodeToNearestRoot,
  addClassNamesToElement,
  mergeRegister,
  removeClassNamesFromElement,
} from "@lexical/utils";
import {
  $createNodeSelection,
  $getNodeFromDOMNode,
  $getSelection,
  $isNodeSelection,
  $isParagraphNode,
  $isRangeSelection,
  $isRootOrShadowRoot,
  $isTextNode,
  $setSelection,
  CLICK_COMMAND,
  COMMAND_PRIORITY_EDITOR,
  COMMAND_PRIORITY_LOW,
  KEY_ENTER_COMMAND,
  type LexicalNode,
} from "lexical";
import { useEffect } from "react";
import { $replaceWithHorizontalRule } from "../markdown/transformers";

const toggleNodeSelection = (node: LexicalNode, shiftKey = false) => {
  const selection = $getSelection();
  const wasSelected = node.isSelected();
  const key = node.getKey();
  const nodeSelection =
    shiftKey && $isNodeSelection(selection)
      ? selection
      : $createNodeSelection();

  if (!($isNodeSelection(selection) && shiftKey)) {
    $setSelection(nodeSelection);
  }

  if (wasSelected) {
    nodeSelection.delete(key);
    return;
  }

  nodeSelection.add(key);
};

const getClickedHorizontalRuleNode = (target: EventTarget | null) => {
  if (!(target instanceof Node)) {
    return null;
  }

  const node = $getNodeFromDOMNode(target);
  return $isHorizontalRuleNode(node) ? node : null;
};

const syncHorizontalRuleSelectionClass = (
  editor: ReturnType<typeof useLexicalComposerContext>[0],
  nodeKey: string,
  selectedClassName: string
) => {
  const element = editor.getElementByKey(nodeKey);
  if (!element) {
    return;
  }

  const node = $getNodeFromDOMNode(element);
  if (!$isHorizontalRuleNode(node)) {
    return;
  }

  if (node.isSelected()) {
    addClassNamesToElement(element, selectedClassName);
    return;
  }

  removeClassNamesFromElement(element, selectedClassName);
};

const registerHorizontalRuleInsertCommand = (
  editor: ReturnType<typeof useLexicalComposerContext>[0]
) => {
  return editor.registerCommand(
    INSERT_HORIZONTAL_RULE_COMMAND,
    () => {
      const selection = $getSelection();
      if (!$isRangeSelection(selection)) {
        return false;
      }

      $insertNodeToNearestRoot($createHorizontalRuleNode());
      return true;
    },
    COMMAND_PRIORITY_EDITOR
  );
};

const registerHorizontalRuleClickCommand = (
  editor: ReturnType<typeof useLexicalComposerContext>[0]
) => {
  return editor.registerCommand(
    CLICK_COMMAND,
    (event) => {
      const node = getClickedHorizontalRuleNode(event.target);
      if (!node) {
        return false;
      }

      toggleNodeSelection(node, event.shiftKey);
      return true;
    },
    COMMAND_PRIORITY_LOW
  );
};

const registerHorizontalRuleEnterShortcut = (
  editor: ReturnType<typeof useLexicalComposerContext>[0]
) => {
  return editor.registerCommand(
    KEY_ENTER_COMMAND,
    (event) => {
      if (event?.shiftKey) {
        return false;
      }

      const selection = $getSelection();
      if (!($isRangeSelection(selection) && selection.isCollapsed())) {
        return false;
      }

      const anchorNode = selection.anchor.getNode();
      if (!$isTextNode(anchorNode)) {
        return false;
      }

      const parentNode = anchorNode.getParent();
      if (
        parentNode === null ||
        !$isParagraphNode(parentNode) ||
        !$isRootOrShadowRoot(parentNode.getParent()) ||
        parentNode.getChildrenSize() !== 1 ||
        parentNode.getFirstChild() !== anchorNode ||
        parentNode.getTextContent() !== "---" ||
        selection.anchor.offset !== anchorNode.getTextContent().length
      ) {
        return false;
      }

      $replaceWithHorizontalRule(parentNode, true);
      if (event !== null) {
        event.preventDefault();
      }
      return true;
    },
    COMMAND_PRIORITY_LOW
  );
};

const registerHorizontalRuleMutationListener = (
  editor: ReturnType<typeof useLexicalComposerContext>[0],
  selectedClassName: string
) => {
  return editor.registerMutationListener(HorizontalRuleNode, (nodes) => {
    editor.read(() => {
      for (const [nodeKey, mutation] of nodes) {
        if (mutation === "destroyed") {
          continue;
        }

        syncHorizontalRuleSelectionClass(editor, nodeKey, selectedClassName);
      }
    });
  });
};

export function HorizontalRulePlugin() {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    const hrSelectedClassName = editor._config.theme.hrSelected ?? "selected";

    return mergeRegister(
      registerHorizontalRuleInsertCommand(editor),
      registerHorizontalRuleClickCommand(editor),
      registerHorizontalRuleEnterShortcut(editor),
      registerHorizontalRuleMutationListener(editor, hrSelectedClassName)
    );
  }, [editor]);

  return null;
}

