import {
  applyBgColor,
  applyTextColor,
  toggleToolbarFormat,
} from "../floating-toolbar/actions";
import { OPEN_FLOATING_LINK_EDITOR_COMMAND } from "../floating-toolbar/link-command";
import { LINK_PLACEHOLDER_URL } from "../link-behavior/utils";
import { ALIGN_ACTIONS, INLINE_FORMAT_ACTIONS } from "./constants";
import { InsertPopover } from "./insert-popover";
import { fullToolbarUiReducer } from "./reducer";
import { INITIAL_UI_STATE } from "./types";
import { useToolbarState } from "./use-toolbar-state";

interface FullToolbarPluginProps {
  className?: string;
  /** Slash command ids resolved from the enabled feature set. */
  commandIds?: readonly string[];
}

export const FullToolbarPlugin = memo(function FullToolbarPlugin({
  className,
  commandIds,
}: FullToolbarPluginProps) {
  const [editor] = useLexicalComposerContext();
  const { blockType, formats, setBlockType } = useToolbarState();
  const [uiState, dispatchUi] = useReducer(
    fullToolbarUiReducer,
    INITIAL_UI_STATE
  );
  const { activeInsertIndex, insertOpen } = uiState;

  const handleBlockTypeChange = useCallback(
    (value: BlockTypeValue) => {
      setBlockType(value);
    },
    [setBlockType]
  );

  const handleLinkToggle = () => {
    if (formats.isLink) {
      editor.dispatchCommand(TOGGLE_LINK_COMMAND, null);
      return;
    }
    editor.dispatchCommand(TOGGLE_LINK_COMMAND, LINK_PLACEHOLDER_URL);
    editor.dispatchCommand(OPEN_FLOATING_LINK_EDITOR_COMMAND, undefined);
  };

  return (
    <div
      aria-label="Formatting toolbar"
      className={cn("flex flex-wrap items-center gap-0.5", className)}
      role="toolbar"
    >
      <TooltipProvider>
        <ToolbarTooltip label="Undo">
          <Button
            aria-label="Undo"
            onClick={() => editor.dispatchCommand(UNDO_COMMAND, undefined)}
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <UndoIcon />
          </Button>
        </ToolbarTooltip>
        <ToolbarTooltip label="Redo">
          <Button
            aria-label="Redo"
            onClick={() => editor.dispatchCommand(REDO_COMMAND, undefined)}
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <RedoIcon />
          </Button>
        </ToolbarTooltip>

        <Separator className="mx-0.5 h-4" orientation="vertical" />

        <BlockTypeDrop
          blockType={blockType}
          commandIds={commandIds}
          editor={editor}
          onBlockTypeChange={handleBlockTypeChange}
        />

