import { $createCodeNode } from "@lexical/code";
import { $createHorizontalRuleNode } from "@lexical/extension";
import {
  $createListItemNode,
  $createListNode,
  type ListType,
} from "@lexical/list";
import {
  $createHeadingNode,
  $createQuoteNode,
  type HeadingTagType,
} from "@lexical/rich-text";
import {
  $createTableCellNode,
  $createTableNode,
  $createTableRowNode,
} from "@lexical/table";
import {
  $createParagraphNode,
  $createTextNode,
  $isParagraphNode,
  type ElementNode,
} from "lexical";
import type { FeatureSlashCommand, SlashCommandId } from "./types";
import { replaceCurrentBlock } from "./utils";

const replaceElementChildren = (
  targetElement: ElementNode,
  nextElement: ElementNode
) => {
  for (const child of targetElement.getChildren()) {
    nextElement.append(child);
  }

  targetElement.replace(nextElement);
};

const applyParagraphCommand = (targetElement: ElementNode) => {
  if ($isParagraphNode(targetElement)) {
    targetElement.selectEnd();
    return;
  }

  const paragraph = $createParagraphNode();
  replaceElementChildren(targetElement, paragraph);
  paragraph.selectEnd();
};

const applyHeadingCommand = (
  targetElement: ElementNode,
  headingTag: HeadingTagType
) => {
  const heading = $createHeadingNode(headingTag);
  replaceElementChildren(targetElement, heading);
  heading.selectEnd();
};

const applyQuoteCommand = (targetElement: ElementNode) => {
  const quote = $createQuoteNode();
  replaceElementChildren(targetElement, quote);
  quote.selectEnd();
};

const applyCodeCommand = (targetElement: ElementNode) => {
  const code = $createCodeNode();
  targetElement.replace(code);
  code.select();
};

const applyListCommand = (targetElement: ElementNode, listType: ListType) => {
  const list = $createListNode(listType);
  const item = $createListItemNode();

  for (const child of targetElement.getChildren()) {
    item.append(child);
  }

  list.append(item);
  targetElement.replace(list);
  item.selectEnd();
};

const createTableCell = (textContent: string, isHeader: boolean) => {
  const tableCell = $createTableCellNode(isHeader ? 1 : 0);
  const paragraph = $createParagraphNode();

  paragraph.append($createTextNode(textContent));
  tableCell.append(paragraph);

  return tableCell;
};

const applyTableCommand = (targetElement: ElementNode) => {
  const tableNode = $createTableNode();
  const headerRow = $createTableRowNode();
  const bodyRow = $createTableRowNode();

  headerRow.append(createTableCell("Column 1", true));
  headerRow.append(createTableCell("Column 2", true));
  headerRow.append(createTableCell("Column 3", true));

  bodyRow.append(createTableCell("", false));
  bodyRow.append(createTableCell("", false));
  bodyRow.append(createTableCell("", false));

  tableNode.append(headerRow);
  tableNode.append(bodyRow);

  targetElement.replace(tableNode);
  bodyRow.getFirstChild()?.selectEnd();
};

const applyDividerCommand = (targetElement: ElementNode) => {
  const horizontalRule = $createHorizontalRuleNode();
  const paragraph = $createParagraphNode();

  targetElement.replace(horizontalRule);
  horizontalRule.insertAfter(paragraph);
  paragraph.select();
};

/**
 * Core-owned executors. Feature-scoped executors live beside their features
 * and reach the menu through their descriptor's `run` instead.
 */
export const CORE_SLASH_COMMAND_EXECUTORS: Record<
  SlashCommandId,
  ((element: ElementNode) => void) | undefined
> = {
  bullet: (element) => applyListCommand(element, "bullet"),
  check: (element) => applyListCommand(element, "check"),
  code: applyCodeCommand,
  collapsible: undefined,
  columns: undefined,
  excalidraw: undefined,
  h1: (element) => applyHeadingCommand(element, "h1"),
  h2: (element) => applyHeadingCommand(element, "h2"),
  h3: (element) => applyHeadingCommand(element, "h3"),
  hr: applyDividerCommand,
  image: undefined,
  math: undefined,
  number: (element) => applyListCommand(element, "number"),
  paragraph: applyParagraphCommand,
  quote: applyQuoteCommand,
  table: applyTableCommand,
  youtube: undefined,
};

/**
 * Runtime registry for feature-contributed command runs. The composition
 * surface registers every installed extra's contributions at mount time, so
 * core surfaces (slash menu, toolbar dropdowns) can execute feature actions
 * without importing any feature module statically.
 */
const featureRunners = new Map<string, FeatureSlashCommand["run"]>();

export const registerSlashRunner = (
  id: string,
  run: FeatureSlashCommand["run"]
): void => {
  featureRunners.set(id, run);
};

export const unregisterSlashRunner = (id: string): void => {
  featureRunners.delete(id);
};

export const getSlashRunner = (
  id: string
): FeatureSlashCommand["run"] | undefined => {
  const featureRun = featureRunners.get(id);
  if (featureRun) {
    return featureRun;
  }

  const executor = CORE_SLASH_COMMAND_EXECUTORS[id as SlashCommandId];
  if (!executor) {
    return undefined;
  }

  return (editor) => {
    replaceCurrentBlock(editor, executor);
  };
};

"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { mergeRegister } from "@lexical/utils";
import {
  $getSelection,
  $isRangeSelection,
  $isTextNode,
  COMMAND_PRIORITY_HIGH,
  KEY_ARROW_DOWN_COMMAND,
  KEY_ARROW_UP_COMMAND,
  KEY_ENTER_COMMAND,
  KEY_ESCAPE_COMMAND,
} from "lexical";
import { useEffect, useEffectEvent, useReducer, useRef } from "react";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { cn } from "@/lib/utils";
import { createSlashMenuAnchor, getSelectionRectangle } from "./anchor";
import type { FeatureSlashCommand, SlashCommandSelection } from "./types";
import {
  filterSlashCommands,
  getFirstCommandId,
  getNeighborCommandId,
  getSelectedCommandIndex,
  getSlashQueryMatch,
  hasSelectedCommand,
} from "./utils";

const SLASH_MENU_COLLISION_AVOIDANCE = {
  align: "none",
  fallbackAxisSide: "none",
  side: "flip",
} as const;

export interface SlashCommandPluginProps {
  /**
   * Resolved slash-menu contributions: the core block types plus every entry
   * contributed by installed feature descriptors. The composition surface
   * builds this list — the menu renders exactly what it receives.
   */
  commands: readonly FeatureSlashCommand[];
}

interface SlashCommandState {
  isOpen: boolean;
  query: string;
  rawSelectedCommandId: SlashCommandSelection;
}

type SlashCommandAction =
  | { type: "patch"; payload: Partial<SlashCommandState> }
  | {
      type: "move-selected-command";
      payload: {
        commands: readonly FeatureSlashCommand[];
        direction: "down" | "up";
      };
    };

const createInitialSlashCommandState = (
  rawSelectedCommandId: SlashCommandSelection
): SlashCommandState => ({
  isOpen: false,
  query: "",
  rawSelectedCommandId,
});

const applySlashCommandPatch = (
  state: SlashCommandState,
  patch: Partial<SlashCommandState>
): SlashCommandState => {
  for (const key of Object.keys(patch) as Array<keyof SlashCommandState>) {
    if (state[key] !== patch[key]) {
      return { ...state, ...patch };
    }
  }

  return state;
};

const slashCommandReducer = (
  state: SlashCommandState,
  action: SlashCommandAction
): SlashCommandState => {
  switch (action.type) {
    case "patch": {
      return applySlashCommandPatch(state, action.payload);
    }
    case "move-selected-command": {
      return applySlashCommandPatch(state, {
        rawSelectedCommandId: getNeighborCommandId(
          action.payload.commands.map((entry) => entry.command),
          state.rawSelectedCommandId,
          action.payload.direction
        ),
      });
    }
    default: {
      return state;
    }
  }
};

export function SlashCommandPlugin({ commands }: SlashCommandPluginProps) {
  const [editor] = useLexicalComposerContext();
  const [state, dispatch] = useReducer(
    slashCommandReducer,
    getFirstCommandId(commands.map((entry) => entry.command)),
    createInitialSlashCommandState
  );
  const { isOpen, query, rawSelectedCommandId } = state;
  const commandListRef = useRef<HTMLDivElement | null>(null);
  const animationFrameRef = useRef<number | null>(null);
  const lastPointerPositionRef = useRef<{ x: number; y: number } | null>(null);

  const filteredCommands = filterSlashCommands(
    commands.map((entry) => entry.command),
    query
  );
  const filteredEntries = commands.filter((entry) => {
    return filteredCommands.some((command) => command.id === entry.command.id);
  });

  const selectedCommandId: SlashCommandSelection = (() => {
    if (filteredCommands.length === 0) {
      return "";
    }

    return hasSelectedCommand(filteredCommands, rawSelectedCommandId)
      ? rawSelectedCommandId
      : getFirstCommandId(filteredCommands);
  })();

  const selectedIndex = getSelectedCommandIndex(
    filteredCommands,
    selectedCommandId
  );

  const anchor = createSlashMenuAnchor(editor);

  const updateSlashMenu = () => {
    const selection = $getSelection();
    const isCollapsedRangeSelection =
      $isRangeSelection(selection) && selection.isCollapsed();

    if (!isCollapsedRangeSelection) {
      dispatch({ type: "patch", payload: { isOpen: false } });
      return;
    }

    const node = selection.anchor.getNode();
    if (!$isTextNode(node)) {
      dispatch({ type: "patch", payload: { isOpen: false } });
      return;
    }

    const textUpToCursor = node
      .getTextContent()
      .slice(0, selection.anchor.offset);
    const nextQuery = getSlashQueryMatch(textUpToCursor);

    if (nextQuery === null) {
      dispatch({ type: "patch", payload: { isOpen: false } });
      return;
    }

    if (!getSelectionRectangle(editor)) {
      dispatch({ type: "patch", payload: { isOpen: false } });
      return;
    }

    dispatch({
      type: "patch",
      payload: { isOpen: true, query: nextQuery },
    });
  };

  const scheduleSlashMenuUpdate = useEffectEvent(() => {
    if (animationFrameRef.current !== null) {
      return;
    }

    animationFrameRef.current = window.requestAnimationFrame(() => {
      animationFrameRef.current = null;
      editor.getEditorState().read(() => {
        updateSlashMenu();
      });
    });
  });

  const executeEntry = useEffectEvent((entry: FeatureSlashCommand) => {
    dispatch({ type: "patch", payload: { isOpen: false } });
    entry.run(editor);
  });

  useEffect(() => {
    if (!(isOpen && selectedCommandId)) {
      return;
    }

    const animationFrameId = window.requestAnimationFrame(() => {
      const selectedItemSelector = `[cmdk-item=""][data-value="${window.CSS.escape(selectedCommandId)}"]`;
      const selectedItem =
        commandListRef.current?.querySelector<HTMLElement>(
          selectedItemSelector
        );

      selectedItem?.scrollIntoView({ block: "nearest" });
    });

    return () => {
      window.cancelAnimationFrame(animationFrameId);
    };
  }, [isOpen, selectedCommandId]);

  useEffect(() => {
    return editor.registerUpdateListener(() => {
      scheduleSlashMenuUpdate();
    });
  }, [editor]);

  useEffect(() => {
    return () => {
      if (animationFrameRef.current !== null) {
        window.cancelAnimationFrame(animationFrameRef.current);
      }
      animationFrameRef.current = null;
    };
  }, []);

  const onKeyCommand = useEffectEvent(
    (command: "arrow-down" | "arrow-up" | "enter" | "escape") => {
      switch (command) {
        case "arrow-down": {
          dispatch({
            type: "move-selected-command",
            payload: { commands, direction: "down" },
          });
          return;
        }
        case "arrow-up": {
          dispatch({
            type: "move-selected-command",
            payload: { commands, direction: "up" },
          });
          return;
        }
        case "enter": {
          const selectedEntry = filteredEntries[selectedIndex];
          if (selectedEntry) {
            executeEntry(selectedEntry);
          }
          return;
        }
        case "escape": {
          dispatch({ type: "patch", payload: { isOpen: false } });
          return;
        }
        default: {
          return;
        }
      }
    }
  );

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    return mergeRegister(
      editor.registerCommand(
        KEY_ARROW_DOWN_COMMAND,
        (event) => {
          event.preventDefault();
          onKeyCommand("arrow-down");
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ARROW_UP_COMMAND,
        (event) => {
          event.preventDefault();
          onKeyCommand("arrow-up");
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ENTER_COMMAND,
        (event) => {
          event?.preventDefault();
          onKeyCommand("enter");
          return true;
        },
        COMMAND_PRIORITY_HIGH
      ),
      editor.registerCommand(
        KEY_ESCAPE_COMMAND,
        () => {
          onKeyCommand("escape");
          return true;
        },
        COMMAND_PRIORITY_HIGH
      )
    );
  }, [editor, isOpen]);

  return (
    <PopoverPrimitive.Root
      modal={false}
      open={isOpen && filteredCommands.length > 0}
    >
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Positioner
          align="start"
          anchor={anchor}
          className="isolate z-50"
          collisionAvoidance={SLASH_MENU_COLLISION_AVOIDANCE}
          positionMethod="fixed"
          side="bottom"
          sideOffset={4}
        >
          <PopoverPrimitive.Popup
            className={cn(
              "data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:fade-in-0 data-open:zoom-in-95 data-closed:fade-out-0 data-closed:zoom-out-95 z-50 flex w-72 origin-(--transform-origin) flex-col overflow-hidden rounded-lg bg-popover p-0 text-popover-foreground text-sm shadow-md outline-hidden ring-1 ring-foreground/10 duration-100 data-closed:animate-out data-open:animate-in"
            )}
            data-slot="slash-command-popover"
            finalFocus={false}
            initialFocus={false}
            onFocus={(event) => {
              // `initialFocus: false` makes the focus manager grab focus for
              // the popup, stealing the caret from the editor. Bounce focus
              // back to the editor root so typing continues seamlessly.
              const rootElement = editor.getRootElement();
              if (
                rootElement &&
                event.target !== rootElement &&
                !rootElement.contains(event.target)
              ) {
                rootElement.focus({ preventScroll: true });
              }
            }}
          >
            <Command shouldFilter={false} value={selectedCommandId}>
              <CommandList ref={commandListRef}>
                <CommandGroup heading="Blocks">
                  {filteredEntries.map((entry, index) => {
                    const command = entry.command;
                    return (
                      <CommandItem
                        className={
                          index === selectedIndex
                            ? "bg-accent text-accent-foreground"
                            : ""
                        }
                        key={command.id}
                        onMouseMove={(event) => {
                          const previousPosition =
                            lastPointerPositionRef.current;
                          lastPointerPositionRef.current = {
                            x: event.clientX,
                            y: event.clientY,
                          };

                          if (!previousPosition) {
                            return;
                          }

                          const hasPointerMoved =
                            previousPosition.x !== event.clientX ||
                            previousPosition.y !== event.clientY;

                          if (!hasPointerMoved) {
                            return;
                          }

                          dispatch({
                            type: "patch",
                            payload: { rawSelectedCommandId: command.id },
                          });
                        }}
                        onSelect={() => executeEntry(entry)}
                        value={command.id}
                      >
                        <command.icon className="size-4 shrink-0 text-muted-foreground" />
                        <div className="flex flex-col">
                          <span className="text-sm">{command.label}</span>
                          <span className="text-muted-foreground text-xs">
                            {command.description}
                          </span>
                        </div>
                      </CommandItem>
                    );
                  })}
                </CommandGroup>
                {filteredCommands.length === 0 ? (
                  <CommandEmpty>No results found</CommandEmpty>
                ) : null}
              </CommandList>
            </Command>
          </PopoverPrimitive.Popup>
        </PopoverPrimitive.Positioner>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
}

import type { LexicalEditor } from "lexical";
import type { LucideIcon } from "lucide-react";

export type SlashCommandId =
  | "paragraph"
  | "h1"
  | "h2"
  | "h3"
  | "quote"
  | "code"
  | "bullet"
  | "number"
  | "check"
  | "math"
  | "image"
  | "youtube"
  | "excalidraw"
  | "collapsible"
  | "columns"
  | "table"
  | "hr";

export type SlashCommandSelection = SlashCommandId | "";

export interface SlashCommand {
  /** Always show regardless of feature toggles (base block types). */
  alwaysOn?: boolean;
  description: string;
  icon: LucideIcon;
  id: SlashCommandId;
  keywords: string[];
  label: string;
}

/**
 * A slash-menu contribution from a feature descriptor: the rendered menu
 * entry plus what happens when the consumer selects it. Runs receive the
 * editor so features can dispatch their own insert commands or mutate the
 * document directly.
 */
export interface FeatureSlashCommand {
  command: SlashCommand;
  run: (editor: LexicalEditor) => void;
}

export interface SlashMenuPosition {
  left: number;
  top: number;
}

export interface SlashMenuAnchor {
  getBoundingClientRect: () => DOMRect;
  getClientRects: () => DOMRectList;
}

import {
  $getSelection,
  $isRangeSelection,
  $isTextNode,
  type ElementNode,
  type LexicalEditor,
} from "lexical";
import type { SlashCommand, SlashCommandSelection } from "./types";

export const SLASH_QUERY_PATTERN = /^\/(\w*)$/;

export const filterSlashCommands = (
  commands: SlashCommand[],
  query: string
): SlashCommand[] => {
  if (!query) {
    return commands;
  }

  const normalizedQuery = query.toLowerCase();

  return commands.filter((command) => {
    return (
      command.label.toLowerCase().includes(normalizedQuery) ||
      command.keywords.some((keyword) => keyword.includes(normalizedQuery))
    );
  });
};

export const getFirstCommandId = (
  commands: SlashCommand[]
): SlashCommandSelection => {
  return commands[0]?.id ?? "";
};

export const getSelectedCommandIndex = (
  commands: SlashCommand[],
  selectedCommandId: SlashCommandSelection
): number => {
  return commands.findIndex((command) => command.id === selectedCommandId);
};

export const getNeighborCommandId = (
  commands: SlashCommand[],
  selectedCommandId: SlashCommandSelection,
  direction: "down" | "up"
): SlashCommandSelection => {
  const currentIndex = getSelectedCommandIndex(commands, selectedCommandId);

  if (currentIndex < 0) {
    return getFirstCommandId(commands);
  }

  const nextIndex =
    direction === "down"
      ? Math.min(currentIndex + 1, commands.length - 1)
      : Math.max(currentIndex - 1, 0);

  return commands[nextIndex]?.id ?? selectedCommandId;
};

export const hasSelectedCommand = (
  commands: SlashCommand[],
  selectedCommandId: SlashCommandSelection
): boolean => {
  return commands.some((command) => command.id === selectedCommandId);
};

export const getSlashQueryMatch = (textUpToCursor: string): string | null => {
  const match = textUpToCursor.match(SLASH_QUERY_PATTERN);

  return match?.[1] ?? null;
};

/**
 * Runs a block-level replacement against the current selection: clears the
 * text content of the selected text node and hands the enclosing top-level
 * element to the callback. Mirrors the flow the slash menu has always used
 * for direct executors.
 */
export const replaceCurrentBlock = (
  editor: LexicalEditor,
  replace: (element: ElementNode) => void
): void => {
  editor.update(() => {
    const selection = $getSelection();

    if (!$isRangeSelection(selection)) {
      return;
    }

    const node = selection.anchor.getNode();

    if (!$isTextNode(node)) {
      return;
    }

    node.setTextContent("");
    replace(node.getTopLevelElementOrThrow());
  });
};

